void init_crypto_sbox(void) {
    unsigned char *sbox = (unsigned char *)0x00405100;
    for (int i = 0; i < 256; i++) {
        sbox[i] = (unsigned char)(((i * 31) ^ 0x5A) % 256);
    }
}

unsigned int transform_serial_block(char *param_1) {
    unsigned char *sbox = (unsigned char *)0x00405100;
    unsigned int hash = 0x811C9DC5;
    for (int i = 0; i < 4; i++) {
        unsigned char b = sbox[(unsigned char)param_1[i]];
        hash = (hash ^ b) * 0x01000193;
    }
    return hash;
}

int validate_license_tier(char *param_1, int param_2) {
    if (param_1 == 0) return 0;
    unsigned int h1 = transform_serial_block(param_1);
    unsigned int h2 = transform_serial_block(param_1 + 5);
    unsigned int *magics = (unsigned int *)0x00405200;
    unsigned int expected = magics[param_2];
    return ((h1 ^ h2) == expected) ? 1 : 0;
}
